import{_ as e,o as d,c as o,a5 as r}from"./chunks/framework.DukzBDYY.js";const f=JSON.parse('{"title":"Template Reference","description":"","frontmatter":{},"headers":[],"relativePath":"guides/reference.md","filePath":"guides/reference.md"}'),a={name:"guides/reference.md"};function c(s,t,l,h,i,n){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="template-reference" tabindex="-1">Template Reference <a class="header-anchor" href="#template-reference" aria-label="Permalink to &quot;Template Reference&quot;">​</a></h1><h2 id="order-and-cart" tabindex="-1">Order and cart <a class="header-anchor" href="#order-and-cart" aria-label="Permalink to &quot;Order and cart&quot;">​</a></h2><p>Delivery Slots adds these to every Commerce order and cart:</p><table tabindex="0"><thead><tr><th></th><th>Returns</th></tr></thead><tbody><tr><td><code>cart.deliverySlotDays</code></td><td>The <a href="#day">days</a> to choose from, for the cart’s shipping method</td></tr><tr><td><code>cart.getDeliverySlotDays(&#39;handle&#39;)</code></td><td>The days for another shipping method</td></tr><tr><td><code>cart.hasDeliverySlots</code></td><td>Whether the cart’s shipping method has slots</td></tr><tr><td><code>cart.getHasDeliverySlots(&#39;handle&#39;)</code></td><td>Whether another shipping method has slots</td></tr><tr><td><code>cart.deliverySlot</code></td><td>The chosen <a href="#delivery-slot">slot</a>, or <code>null</code></td></tr><tr><td><code>cart.getFirstError(&#39;deliverySlot&#39;)</code></td><td>Why the slot couldn’t be held or the order paid for</td></tr></tbody></table><h2 id="day" tabindex="-1">Day <a class="header-anchor" href="#day" aria-label="Permalink to &quot;Day&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><code>date</code></td><td>The day</td></tr><tr><td><code>slots</code></td><td>Its <a href="#slot">slots</a>, including full ones</td></tr><tr><td><code>openSlots</code></td><td>Slots that aren’t full</td></tr><tr><td><code>isAvailable</code></td><td>Whether any slot can be chosen</td></tr><tr><td><code>unavailableReason</code></td><td>Why there are no slots: <em>Closed</em>, a closed day’s label, <em>Not in your area</em> or <em>Ordering has closed</em>. <code>null</code> when the day has slots</td></tr></tbody></table><h2 id="slot" tabindex="-1">Slot <a class="header-anchor" href="#slot" aria-label="Permalink to &quot;Slot&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td>Post this as <code>deliverySlot</code>, such as <code>2026-11-17@08:00</code></td></tr><tr><td><code>label</code></td><td>The times, such as “8 – 10am”</td></tr><tr><td><code>date</code></td><td>When the slot starts</td></tr><tr><td><code>start</code>, <code>end</code></td><td>The times as <code>08:00</code> and <code>10:00</code></td></tr><tr><td><code>capacity</code></td><td>The slot’s limit</td></tr><tr><td><code>left</code></td><td>Places left</td></tr><tr><td><code>isFull</code></td><td>No places left</td></tr><tr><td><code>isLow</code></td><td>Nearly full</td></tr><tr><td><code>fee</code></td><td>Its zone’s fee, or 0</td></tr></tbody></table><h2 id="delivery-slot" tabindex="-1">Delivery slot <a class="header-anchor" href="#delivery-slot" aria-label="Permalink to &quot;Delivery slot&quot;">​</a></h2><p><code>order.deliverySlot</code>, the slot chosen for an order.</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>The day and times, such as “Tuesday 17 November, 8 – 10am”</td></tr><tr><td><code>timeLabel</code></td><td>The times, such as “8 – 10am”</td></tr><tr><td><code>startDate</code>, <code>endDate</code></td><td>When it starts and ends</td></tr><tr><td><code>date</code>, <code>start</code>, <code>end</code></td><td><code>2026-11-17</code>, <code>08:00</code>, <code>10:00</code></td></tr><tr><td><code>value</code></td><td><code>2026-11-17@08:00</code></td></tr><tr><td><code>zone</code></td><td>The drawn zone’s entry, or <code>null</code></td></tr><tr><td><code>zoneName</code></td><td>The zone’s name, for a postcode or drawn zone, or <code>null</code></td></tr><tr><td><code>fee</code></td><td>The slot’s fee</td></tr><tr><td><code>isBooked</code></td><td><code>true</code> once the order is complete, <code>false</code> while it’s held</td></tr><tr><td><code>calendarUrl</code></td><td>A link to download the slot as a calendar event (<code>.ics</code>). Works for completed orders</td></tr></tbody></table><h2 id="form-fields" tabindex="-1">Form fields <a class="header-anchor" href="#form-fields" aria-label="Permalink to &quot;Form fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Action</th><th>Description</th></tr></thead><tbody><tr><td><code>deliverySlot</code></td><td><code>commerce/cart/update-cart</code></td><td>Holds the slot for the cart. Empty clears it</td></tr><tr><td><code>deliverySlot</code></td><td><code>delivery-slots/slots/choose</code></td><td>The same, on its own (<a href="/guides/javascript">JavaScript Checkouts</a>)</td></tr></tbody></table><h2 id="times" tabindex="-1">Times <a class="header-anchor" href="#times" aria-label="Permalink to &quot;Times&quot;">​</a></h2><p>Slot times show as “8 – 10am” and “10am – 12pm” on sites in English, and as “08:00 – 10:00” in other languages. For another format, use <code>startDate</code> and <code>endDate</code> with Craft’s <code>date</code> filter.</p>',15)])])}const y=e(a,[["render",c]]);export{f as __pageData,y as default};
